const menus={coffee:[['Mountain cappuccino','Espresso, silky steamed milk, a little mountain magic.',180],['The slow morning latte','A mellow double shot with creamy milk.',200],['Classic cold coffee','Chilled, blended, and made for sunny afternoons.',220],['Himalayan masala chai','Tea simmered with warming spices and milk.',100]],food:[['Pesto pasta','Basil pesto, seasonal vegetables, and parmesan.',320],['Grilled mountain sandwich','Toasted bread, fresh vegetables, and melted cheese.',240],['All-day breakfast','Eggs, toast, sautéed vegetables, and a slow start.',280],['Café-style pizza','A crisp base with tomatoes, cheese, and herbs.',360]],sweet:[['Warm chocolate brownie','Rich chocolate, served warm with vanilla ice cream.',220],['Classic cheesecake','Creamy, gently sweet, with a biscuit base.',240],['Pancakes & honey','Fluffy pancakes, honey, and seasonal fruit.',260],['A slice of the day','Ask us what is fresh from the oven today.',180]]};
const tabs=[...document.querySelectorAll('[data-category]')];function menu(category){document.querySelector('#menu-items').innerHTML=menus[category].map(([name,desc,price])=>`<article class="menu-item"><h3>${name}</h3><span class="price">₹${price}</span><p>${desc}</p></article>`).join('');document.querySelector('#menu-items').setAttribute('aria-labelledby',`tab-${category}`);tabs.forEach(t=>{const active=t.dataset.category===category;t.setAttribute('aria-selected',active);t.tabIndex=active?0:-1});document.querySelector('#menu-photo').src=category==='coffee'?'assets/coffee.jpg':'assets/food.jpg';document.querySelector('#menu-photo').alt=category==='coffee'?'Fresh café coffee':'Comfort food from the café'}menu('coffee');tabs.forEach((t,i)=>{t.addEventListener('click',()=>menu(t.dataset.category));t.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=(i+1)%3;if(e.key==='ArrowLeft')next=(i+2)%3;if(e.key==='Home')next=0;if(e.key==='End')next=2;if(next!==undefined){e.preventDefault();tabs[next].focus();menu(tabs[next].dataset.category)}})});
const nav=document.querySelector('nav'),toggle=document.querySelector('.mobile-toggle');toggle.onclick=()=>{const expanded=nav.classList.toggle('expanded');toggle.setAttribute('aria-expanded',expanded)};nav.querySelectorAll('a').forEach(a=>a.onclick=()=>{nav.classList.remove('expanded');toggle.setAttribute('aria-expanded','false')});
const booking=document.querySelector('#booking');document.querySelectorAll('[data-book]').forEach(b=>b.onclick=()=>{document.querySelector('#booking-form').hidden=false;document.querySelector('#visit-summary').hidden=true;booking.showModal()});document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
const date=document.querySelector('[name=date]'),today=new Date();const localDate=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;date.min=localDate;date.value=localDate;document.querySelector('#booking-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const summary=document.querySelector('#visit-summary');summary.replaceChildren();const p=document.createElement('p');p.textContent=`${f.get('name')}, your visit plan: ${f.get('guests')} on ${new Date(f.get('date')+'T12:00:00').toLocaleDateString('en-IN',{dateStyle:'long'})} at ${f.get('time')}.`;summary.append(p);const note=document.createElement('p');note.textContent='Your table is not reserved yet. Call our café team to check availability and confirm.';summary.append(note);const call=document.createElement('a');call.href='tel:+917796764438';call.className='pill';call.textContent='Call to confirm ↗';summary.append(call);summary.hidden=false;e.target.hidden=true};
const lightbox=document.querySelector('#lightbox');document.querySelectorAll('[data-photo]').forEach(b=>b.onclick=()=>{lightbox.querySelector('img').src=b.dataset.photo;lightbox.querySelector('img').alt=b.dataset.caption;lightbox.querySelector('p').textContent=b.dataset.caption;lightbox.showModal()});if(!matchMedia('(prefers-reduced-motion: reduce)').matches){document.body.classList.add('js-motion');const observer=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('.reveal').forEach(e=>observer.observe(e))}
